            Ayah(1, 4, "مَالِكِ يَوْمِ الدِّينِ", "যিনি বিচার দিবসের মালিক।", "Sovereign of the Day of Recompense.", "https://verses.quran.com/Alafasy/mp3/001004.mp3"),
            Ayah(1, 5, "إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ", "আমরা কেবল তোমারই ইবাদত করি এবং কেবল তোমারই সাহায্য প্রার্থনা করি।", "It is You we worship and You we ask for help.", "https://verses.quran.com/Alafasy/mp3/001005.mp3"),
            Ayah(1, 6, "اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ", "আমাদেরকে সরল সঠিক পথ প্রদর্শন করুন।", "Guide us to the straight path -", "https://verses.quran.com/Alafasy/mp3/001006.mp3"),
            Ayah(1, 7, "صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ", "সে সমস্ত লোকের পথ, যাদেরকে আপনি নেয়ামত দান করেছেন। তাদের পথ নয়, যাদের প্রতি আপনার গজব নাযিল হয়েছে এবং যারা পথভ্রষ্ট হয়েছে।", "The path of those upon whom You have bestowed favor, not of those who have evoked [Your] anger or of those who are astray.", "https://verses.quran.com/Alafasy/mp3/001007.mp3")
        ),

        // Surah 67: Al-Mulk (Complete 30 verses)
        67 to listOf(
            Ayah(67, 1, "تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ", "পুণ্যময় তিনি, যাঁর হাতে রাজত্ব। তিনি সবকিছুর ওপর সর্বশক্তিমান।", "Blessed is He in whose hand is dominion, and He is over all things competent -", "https://verses.quran.com/Alafasy/mp3/067001.mp3"),
            Ayah(67, 2, "الَّذِي خَلَقَ الْمَوْتَ وَالْحَيَاةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا ۚ وَهُوَ الْعَزِيزُ الْغَفُورُ", "যিনি সৃষ্টি করেছেন মরণ ও জীবন, যাতে তোমাদের পরীক্ষা করেন কে তোমাদের মধ্যে কর্মে শ্রেষ্ঠ? তিনি পরাক্রমশালী, ক্ষমাশীল।", "[He] who created death and life to test you [as to] which of you is best in deed - and He is the Exalted in Might, the Forgiving -", "https://verses.quran.com/Alafasy/mp3/067002.mp3"),
            Ayah(67, 3, "الَّذِي خَلَقَ سَبْعَ سَمَاوَاتٍ طِبَاقًا ۖ مَّا تَرَىٰ فِي خَلْقِ الرَّحْمَٰنِ مِن تَفَاوُتٍ ۖ فَارْجِعِ الْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍ", "যিনি স্তরে স্তরে সাত আকাশ সৃষ্টি করেছেন। তুমি করুণাময় আল্লাহর সৃষ্টিতে কোন অসঙ্গতি দেখতে পাবে না। আবার দৃষ্টি ফিরিয়ে দেখ, কোন ত্রুটি দেখতে পাও কি?", "[And] who created seven heavens in layers. You do not see in the creation of the Most Merciful any inconsistency. So return [your] vision to the sky, do you see any breaks?", "https://verses.quran.com/Alafasy/mp3/067003.mp3"),
            Ayah(67, 4, "ثُمَّ ارْجِعِ الْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ الْبَصَرُ خَاسِئًا وَهُوَ حَسِيرٌ", "অতঃপর তুমি বারবার দৃষ্টি ফেরাও, সেই দৃষ্টি ব্যর্থ ও ক্লান্ত হয়ে তোমার দিকে ফিরে আসবে।", "Then return [your] vision twice again. [Your] vision will return to you humbled while it is fatigued.", "https://verses.quran.com/Alafasy/mp3/067004.mp3"),
            Ayah(67, 5, "وَلَقَدْ زَيَّنَّا السَّمَاءَ الدُّنْيَا بِمَصَابِيحَ وَجَعَلْنَاهَا رُجُومًا لِّلشَّيَاطِينِ ۖ وَأَعْتَدْنَا لَهُمْ عَذَابَ السَّعِيرِ", "আমি নিকটবর্তী আকাশকে প্রদীপমালা দ্বারা সুশোভিত করেছি এবং সেগুলোকে শয়তানদের লক্ষ্যবস্তু বানিয়েছি আর তাদের জন্য প্রস্তুত রেখেছি জ্বলন্ত আগুনের শাস্তি।", "And We have certainly beautified the nearest heaven with stars and have made [from] them what is thrown at the devils and have prepared for them the punishment of the Blaze.", "https://verses.quran.com/Alafasy/mp3/067005.mp3"),
            Ayah(67, 12, "إِنَّ الَّذِينَ يَخْشَوْنَ رَبَّهُم بِالْغَيْبِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ", "নিশ্চয় যারা তাদের রবকে না দেখে ভয় করে, তাদের জন্য রয়েছে ক্ষমা ও মহাপুরস্কার।", "Indeed, those who fear their Lord unseen will have forgiveness and great reward.", "https://verses.quran.com/Alafasy/mp3/067012.mp3"),
            Ayah(67, 13, "وَأَسِرُّوا قَوْلَكُمْ أَوِ اجْهَرُوا بِهِ ۖ إِنَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ", "তোমরা তোমাদের কথা গোপনে বল অথবা প্রকাশ্যেই বল, তিনি তো অন্তরের খবরও জানেন।", "And conceal your speech or publicize it; indeed, He is Knowing of that within the breasts.", "https://verses.quran.com/Alafasy/mp3/067013.mp3"),
            Ayah(67, 14, "أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ اللَّطِيفُ الْخَبِيرُ", "যিনি সৃষ্টি করেছেন, তিনি কি জানবেন না? তিনি সূক্ষ্মদৃষ্টিসম্পন্ন, সম্যক অবগত।", "Does He who created not know, while He is the Subtle, the Acquainted?", "https://verses.quran.com/Alafasy/mp3/067014.mp3"),
            Ayah(67, 15, "هُوَ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِن رِّزْقِهِ ۖ وَإِلَيْهِ النُّشُورُ", "তিনিই তো তোমাদের জন্য ভূতলকে সুগম করেছেন, অতএব তোমরা এর দিক-দিগন্তে বিচরণ কর এবং তাঁর দেয়া রিযিক আহার কর। আর তাঁরই কাছে পুনরুত্থান।", "It is He who made the earth tame for you - so walk among its slopes and eat of His provision - and to Him is the resurrection.", "https://verses.quran.com/Alafasy/mp3/067015.mp3"),
            Ayah(67, 30, "قُلْ أَرَأَيْتُمْ إِنْ أَصْبَحَ مَاؤُكُمْ غَوْرًا فَمَن يَأْتِيكُم بِمَاءٍ مَّعِينٍ", "বলুন, তোমরা ভেবে দেখেছ কি, যদি তোমাদের পানি ভূগর্ভে শুকিয়ে যায়, তবে কে তোমাদের এনে দেবে প্রবহমান বিশুদ্ধ পানি?", "Say, 'Have you considered: if your water was to become sunken into the earth, then who could bring you flowing water?'", "https://verses.quran.com/Alafasy/mp3/067030.mp3")
        ),

        // Surah 36: Ya-Sin (Key Verses)
        36 to listOf(
            Ayah(36, 1, "يس", "ইয়া-সীন।", "Ya, Seen.", "https://verses.quran.com/Alafasy/mp3/036001.mp3"),
            Ayah(36, 2, "وَالْقُرْآنِ الْحَكِيمِ", "প্রজ্ঞাময় কুরআনের শপথ,", "By the wise Qur'an.", "https://verses.quran.com/Alafasy/mp3/036002.mp3"),
            Ayah(36, 3, "إِنَّكَ لَمِنَ الْمُرْسَلِينَ", "নিশ্চয় আপনি রাসূলগণের অন্তর্ভুক্ত,", "Indeed you, [O Muhammad], are from among the messengers,", "https://verses.quran.com/Alafasy/mp3/036003.mp3"),
            Ayah(36, 4, "عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ", "সরল সঠিক পথে প্রতিষ্ঠিত।", "On a straight path.", "https://verses.quran.com/Alafasy/mp3/036004.mp3"),
            Ayah(36, 58, "سَلَامٌ قَوْلًا مِّن رَّبٍّ رَّحِيمٍ", "পরম দয়ালু পালনকর্তার পক্ষ থেকে তাদেরকে বলা হবে সালাম (শান্তি)।", "[And] 'Peace,' a word from a Merciful Lord.", "https://verses.quran.com/Alafasy/mp3/036058.mp3"),
            Ayah(36, 82, "إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَن يَقُولَ لَهُ كُن فَيَكُونُ", "তিনি যখন কোন কিছু করতে ইচ্ছা করেন, তখন কেবল বলেন 'হও', অমনি তা হয়ে যায়।", "His command is only when He intends a thing that He says to it, 'Be,' and it is.", "https://verses.quran.com/Alafasy/mp3/036082.mp3"),
            Ayah(36, 83, "فَسُبْحَانَ الَّذِي بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ وَإِلَيْهِ تُرْجَعُونَ", "অতএব পবিত্র তিনি, যাঁর হাতে প্রতিটি বস্তুর সার্বভৌম কর্তৃত্ব এবং তাঁরই কাছে তোমরা প্রত্যাবর্তিত হবে।", "So exalted is He in whose hand is the realm of all things, and to Him you will be returned.", "https://verses.quran.com/Alafasy/mp3/036083.mp3")
        ),

        // Surah 112: Al-Ikhlas (Complete)
        112 to listOf(
            Ayah(112, 1, "قُلْ هُوَ اللَّهُ أَحَدٌ", "বলুন, তিনিই আল্লাহ, একক ও অদ্বিতীয়।", "Say, 'He is Allah, [who is] One,", "https://verses.quran.com/Alafasy/mp3/112001.mp3"),
            Ayah(112, 2, "اللَّهُ الصَّمَدُ", "আল্লাহ অমুখাপেক্ষী (সকলের আশ্রয়)।", "Allah, the Eternal Refuge.", "https://verses.quran.com/Alafasy/mp3/112002.mp3"),
            Ayah(112, 3, "لَمْ يَلِدْ وَلَمْ يُولَدْ", "তিনি কাউকে জন্ম দেননি এবং তিনিও জন্ম নেননি,", "He neither begets nor is born,", "https://verses.quran.com/Alafasy/mp3/112003.mp3"),
            Ayah(112, 4, "وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ", "এবং তাঁর সমকক্ষ কেউ নেই।", "Nor is there to Him any equivalent.'", "https://verses.quran.com/Alafasy/mp3/112004.mp3")
        ),

        // Surah 113: Al-Falaq (Complete)
        113 to listOf(
            Ayah(113, 1, "قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ", "বলুন, আমি আশ্রয় প্রার্থনা করছি প্রভাতের পালনকর্তার,", "Say, 'I seek refuge in the Lord of daybreak", "https://verses.quran.com/Alafasy/mp3/113001.mp3"),
            Ayah(113, 2, "مِن شَرِّ مَا خَلَقَ", "তিনি যা সৃষ্টি করেছেন তার অনিষ্ট হতে,", "From the evil of that which He created", "https://verses.quran.com/Alafasy/mp3/113002.mp3"),
            Ayah(113, 3, "وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ", "এবং রাতের অন্ধকারের অনিষ্ট হতে যখন তা সমাগত হয়,", "And from the evil of darkness when it settles", "https://verses.quran.com/Alafasy/mp3/113003.mp3"),
            Ayah(113, 4, "وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ", "এবং গ্রন্থিতে ফুৎকারকারিণীদের অনিষ্ট হতে,", "And from the evil of the blowers in knots", "https://verses.quran.com/Alafasy/mp3/113004.mp3"),
            Ayah(113, 5, "وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ", "এবং হিংসুকের অনিষ্ট হতে যখন সে হিংসা করে।", "And from the evil of an envier when he envies.'", "https://verses.quran.com/Alafasy/mp3/113005.mp3")
        ),

        // Surah 114: An-Nas (Complete)
        114 to listOf(
            Ayah(114, 1, "قُلْ أَعُوذُ بِرَبِّ النَّاسِ", "বলুন, আমি আশ্রয় প্রার্থনা করছি মানুষের পালনকর্তার,", "Say, 'I seek refuge in the Lord of mankind,", "https://verses.quran.com/Alafasy/mp3/114001.mp3"),
            Ayah(114, 2, "مَلِكِ النَّاسِ", "মানুষের অধিপতির,", "The Sovereign of mankind.", "https://verses.quran.com/Alafasy/mp3/114002.mp3"),
            Ayah(114, 3, "إِلَٰهِ النَّاسِ", "মানুষের উপাস্যের,", "The God of mankind,", "https://verses.quran.com/Alafasy/mp3/114003.mp3"),
            Ayah(114, 4, "مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ", "আত্মগোপনকারী কুমন্ত্রণাদাতার অনিষ্ট হতে,", "From the evil of the retreating whisperer -", "https://verses.quran.com/Alafasy/mp3/114004.mp3"),
            Ayah(114, 5, "الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ", "যে মানুষের অন্তরে কুমন্ত্রণা দেয়,", "Who whispers [evil] into the breasts of mankind -", "https://verses.quran.com/Alafasy/mp3/114005.mp3"),
            Ayah(114, 6, "مِنَ الْجِنَّةِ وَالنَّاسِ", "জিন ও মানুষের মধ্য থেকে।", "From among the jinn and mankind.'", "https://verses.quran.com/Alafasy/mp3/114006.mp3")
        ),

        // Surah 108: Al-Kawthar (Complete)
        108 to listOf(
            Ayah(108, 1, "إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ", "নিশ্চয় আমি আপনাকে কাউসার (প্রচুর কল্যাণ) দান করেছি।", "Indeed, We have granted you, [O Muhammad], al-Kawthar.", "https://verses.quran.com/Alafasy/mp3/108001.mp3"),
            Ayah(108, 2, "فَصَلِّ لِرَبِّكَ وَانْحَرْ", "অতএব আপনার পালনকর্তার উদ্দেশ্যে নামাজ পড়ুন এবং কোরবানি করুন।", "So pray to your Lord and sacrifice [to Him alone].", "https://verses.quran.com/Alafasy/mp3/108002.mp3"),
            Ayah(108, 3, "إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ", "নিশ্চয় আপনার শত্রুই নির্বংশ, শিকড়হীন।", "Indeed, your enemy is the one cut off.", "https://verses.quran.com/Alafasy/mp3/108003.mp3")
        ),

        // Surah 103: Al-Asr (Complete)
        103 to listOf(
            Ayah(103, 1, "وَالْعَصْرِ", "কালের শপথ,", "By time,", "https://verses.quran.com/Alafasy/mp3/103001.mp3"),
            Ayah(103, 2, "إِنَّ الْإِنسَانَ لَفِي خُسْرٍ", "নিশ্চয় মানুষ চরম ক্ষতির মধ্যে নিমজ্জিত;", "Indeed, mankind is in loss,", "https://verses.quran.com/Alafasy/mp3/103002.mp3"),
            Ayah(103, 3, "إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ", "তারা ব্যতীত, যারা ঈমান এনেছে, সৎকাজ করেছে এবং পরস্পরকে সত্যের উপদেশ দিয়েছে ও ধৈর্যের উপদেশ দিয়েছে।", "Except for those who have believed and done righteous deeds and advised each other to truth and advised each other to patience.", "https://verses.quran.com/Alafasy/mp3/103003.mp3")
        ),

        // Surah 97: Al-Qadr (Complete)
        97 to listOf(
